import {showChanges,oxygenCases,rankCases} from './changes-scenes.js?v=20261023-physicscomplete01';
const select=(id,label,values,value='')=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${values.map(v=>`<option value="${v}" ${v===value?'selected':''}>${v==='none'?'None of the starting substances':v}</option>`).join('')}</select>`;
export function mountChangesWidget(l,p,root,{save,done,feedback}){const w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const i=w.task,a=w.answers[i]??={},oxygen=l.widget==='changes-oxygen',t=(oxygen?oxygenCases:rankCases)[i],kind=oxygen?'oxygen':'reactivity',$=s=>root.querySelector(s),fields=oxygen?['gain','loss']:['first','second','third'];root.innerHTML=`<p><b>Case ${i+1} / 3</b></p><p>${oxygen?t.equation:t.evidence.join(' ')}</p>`+(oxygen?select('gain','Starting substance gaining oxygen',t.options,a.gain)+select('loss','Starting substance losing oxygen',t.options,a.loss):fields.map((k,j)=>select(k,['Most reactive','Middle','Least reactive'][j],t.answer.slice().sort(),a[k])).join(''))+`<button class="secondary" id="checkChanges">Check my reasoning</button><button class="secondary" id="nextChanges">Next case →</button><p id="changesProgress">${w.passed.length} / 3 cases correct</p>`;fields.forEach(k=>$('#'+k).onchange=e=>{a[k]=e.target.value;save();});showChanges(kind,t,w.passed.includes(i));$('#checkChanges').onclick=()=>{const ok=oxygen?a.gain===t.gain&&a.loss===t.loss:fields.every((k,j)=>a[k]===t.answer[j]);if(!ok){feedback(oxygen?'Follow each starting substance into its product. Oxygen gain is oxidation; oxygen loss is reduction. In direct metal oxidation no listed starting substance loses oxygen.':'Put the displacing metal above the displaced one. Combine both observations, using each label once; compare rates only under the stated controlled conditions.',true);return;}if(!w.passed.includes(i))w.passed.push(i);save();showChanges(kind,t,true);$('#changesProgress').textContent=w.passed.length+' / 3 cases correct';feedback('Correct. The evidence supports the displayed account.');if(w.passed.length===3){p.widgetDone=true;save();done();}};$('#nextChanges').onclick=()=>{w.task=(i+1)%3;save();mountChangesWidget(l,p,root,{save,done,feedback});};}
